/**
 * Sigma's captured catalogue, as the Playwright worker last published it.
 *
 * `public/data/sigma_products.json` is the file the app itself fetches, so this
 * static import is the offline/first-paint copy: the search page and the cards
 * have prices immediately, instead of after a network round-trip. The runtime
 * fetch (`sigmaFeed.ts`) still wins when it returns rows, so a fresh worker run
 * replaces these without a rebuild.
 *
 * Regenerated by `python scripts/sigma_worker.py`; see docs/RETAILER_STRATEGY.md.
 */
import feed from '../../../public/data/sigma_products.json';

export interface SigmaFeedProduct {
  retailerId: 'sigma';
  externalId: string;
  name: string;
  category: string | null;
  priceEgp: number;
  originalPriceEgp: number | null;
  stockStatus: 'in_stock' | 'out_of_stock' | 'limited' | 'unknown';
  productUrl: string;
  imageUrl: string | null;
}

interface SigmaSnapshot {
  capturedAt: string;
  status: string;
  products: SigmaFeedProduct[];
}

export const SIGMA_SNAPSHOT = feed as unknown as SigmaSnapshot;
